/** old-cut → new-cut time knots after the silent gaps were removed (2026-10-22). s(t) = last knot (old<=t): new + (t-old). Generated by .tmp/knots.cjs */
export const KN: Record<string, [number, number][]> = {"as":[[0,0],[14.56,14.53],[15.16,14.53],[19.82,19.17],[20.66,19.17]],"nm":[[0,0],[7.32,7.3],[7.46,7.3],[15.46,15.27],[15.74,15.27],[26.8,26.3],[27,26.3],[38.1,37.37],[38.56,37.37],[43.44,42.23],[49.02,42.23]],"tb":[[0,0],[1.3,1.27],[2.04,1.27],[10.8,10],[11.06,10],[20.02,18.93],[20.22,18.93],[30.24,28.93],[34.92,28.93]]};
export const mkShift = (kn: [number, number][]) => (t: number): number => {
  let i = 0;
  for (let j = 0; j < kn.length; j++) if (kn[j][0] <= t + 1e-6) i = j;
  if (i + 1 < kn.length && kn[i + 1][1] === kn[i][1]) return kn[i][1]; // inside a removed silent gap: everything maps to the join
  return +(kn[i][1] + (t - kn[i][0])).toFixed(3);
};
